import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    public static void main(String[] args) throws Exception {
        List<Path> files = List.of(Path.of("a.txt"), Path.of("b.txt"));
        try (ExecutorService pool = Executors.newFixedThreadPool(2)) {
            List<Future<Long>> counts = new java.util.ArrayList<>();
            for (Path file : files) {
                Callable<Long> task = () -> { try (var lines = Files.lines(file)) { return lines.count(); } };
                counts.add(pool.submit(task));
            }
            for (int i = 0; i < counts.size(); i++) System.out.println(files.get(i) + ": " + counts.get(i).get());
        }
    }
}
